INSERT INTO "policy_center" (
  "id", "name", "description", "full_description", "category", "country", "state",
  "tags", "icon", "color", "type", "purpose", "scope", "requirements",
  "risk_categories", "industries_affected", "governing_authority", "effective_date",
  "version", "legal_status", "official_url", "references", "disable", "metadata", "isActive"
) VALUES
('10000000-0000-4000-8000-000000000001', 'ISO/IEC 42001',
 'International standard for establishing, implementing, maintaining and continually improving an AI management system.',
 'ISO/IEC 42001 specifies requirements for an Artificial Intelligence Management System. It helps organizations govern AI responsibilities, objectives, risk treatment, lifecycle controls, monitoring and continual improvement using a management-system approach.',
 'Standard', 'International', NULL, ARRAY['AI management system','governance','lifecycle'], 'ISO', 'bg-sky-600', 'Voluntary',
 'Provide an auditable management system for responsible development, provision and use of AI.',
 'Organizations of any size that develop, provide or use AI systems.',
 '["Establish an AI policy and accountable governance roles","Assess AI system impacts and risks","Control AI lifecycle processes and third parties","Monitor performance, audit and continually improve the AIMS"]'::jsonb,
 ARRAY['Governance','Accountability','AI lifecycle','Third-party risk'], ARRAY['All industries'], 'ISO and IEC', '2023-12-18', 'ISO/IEC 42001:2023', 'Published',
 'https://www.iso.org/standard/81230.html', '[{"title":"ISO/IEC 42001 official standard page","url":"https://www.iso.org/standard/81230.html"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000002', 'ISO/IEC 27001',
 'International standard for information security management systems and risk-based protection of information assets.',
 'ISO/IEC 27001 defines requirements for an Information Security Management System. In AI governance it provides the security, access control, supplier, incident, continuity and assurance foundation needed to protect models, datasets, infrastructure and AI outputs.',
 'Standard', 'International', NULL, ARRAY['information security','ISMS','cybersecurity'], 'ISO', 'bg-sky-600', 'Voluntary',
 'Protect confidentiality, integrity and availability through a risk-managed information security system.',
 'Organizations managing information assets, including AI data, models, services and infrastructure.',
 '["Maintain an information security risk assessment and treatment process","Implement applicable Annex A controls","Define security roles, policies and evidence","Conduct internal audits, management reviews and corrective actions"]'::jsonb,
 ARRAY['Cybersecurity','Privacy','Access control','Operational resilience'], ARRAY['All industries'], 'ISO and IEC', '2022-10-25', 'ISO/IEC 27001:2022', 'Published',
 'https://www.iso.org/standard/27001', '[{"title":"ISO/IEC 27001 official standard page","url":"https://www.iso.org/standard/27001"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000003', 'ISO/IEC 23894',
 'Guidance for identifying, assessing, treating, monitoring and communicating risks associated with artificial intelligence.',
 'ISO/IEC 23894 provides AI-specific risk management guidance that can be integrated with broader enterprise risk processes. It addresses uncertainty, data and model issues, human oversight, societal impacts and risks throughout the AI system lifecycle.',
 'Guideline', 'International', NULL, ARRAY['AI risk','risk management','trustworthiness'], 'ISO', 'bg-sky-600', 'Voluntary',
 'Help organizations integrate AI-specific risk considerations into established risk management activities.',
 'Organizations developing, deploying, operating or relying on AI systems.',
 '["Establish AI risk context and criteria","Identify risks across the AI lifecycle","Analyze, evaluate and treat AI risks","Monitor, review, record and communicate risk decisions"]'::jsonb,
 ARRAY['Model risk','Bias','Safety','Human oversight'], ARRAY['All industries'], 'ISO and IEC', '2023-02-06', 'ISO/IEC 23894:2023', 'Published',
 'https://www.iso.org/standard/77304.html', '[{"title":"ISO/IEC 23894 official standard page","url":"https://www.iso.org/standard/77304.html"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000004', 'NIST AI Risk Management Framework',
 'Voluntary, rights-preserving framework organized around Govern, Map, Measure and Manage functions.',
 'NIST AI RMF 1.0 helps organizations design, develop, deploy and evaluate trustworthy AI. It is sector- and use-case-agnostic and frames practical outcomes for governance, contextual mapping, measurement and ongoing risk management.',
 'Framework', 'International', NULL, ARRAY['NIST','AI RMF','trustworthy AI'], 'NIST', 'bg-slate-900', 'Voluntary',
 'Improve the ability to incorporate trustworthiness considerations into AI products, services and systems.',
 'AI actors and organizations of all sizes and sectors across the complete AI lifecycle.',
 '["Govern AI risk culture and accountability","Map context, impacts and affected stakeholders","Measure trustworthiness and risk","Manage prioritized risks and monitor deployed systems"]'::jsonb,
 ARRAY['Validity','Safety','Security','Transparency','Privacy','Fairness'], ARRAY['All industries'], 'U.S. National Institute of Standards and Technology', '2023-01-26', 'AI RMF 1.0', 'Published; revision in progress',
 'https://www.nist.gov/itl/ai-risk-management-framework', '[{"title":"NIST AI RMF","url":"https://www.nist.gov/itl/ai-risk-management-framework"},{"title":"AI RMF 1.0 publication","url":"https://doi.org/10.6028/NIST.AI.100-1"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000005', 'OECD AI Principles',
 'Intergovernmental principles for innovative and trustworthy AI that respects human rights and democratic values.',
 'Adopted in 2019 and updated in 2024, the OECD AI Principles contain five values-based principles and five policy recommendations. They cover inclusive growth, rights and fairness, transparency, robustness, security, safety and accountability.',
 'Guideline', 'International', NULL, ARRAY['OECD','human rights','responsible AI'], 'OECD', 'bg-blue-700', 'Voluntary',
 'Create an interoperable, human-centric foundation for trustworthy AI policy and practice.',
 'Governments and AI actors throughout the AI system lifecycle.',
 '["Promote inclusive growth and sustainable well-being","Respect human rights, fairness and privacy","Provide transparency and meaningful information","Ensure robustness, security, safety and accountability"]'::jsonb,
 ARRAY['Human rights','Fairness','Transparency','Security','Accountability'], ARRAY['All industries','Public sector'], 'Organisation for Economic Co-operation and Development', '2019-05-22', 'Updated 2024', 'Adopted recommendation',
 'https://www.oecd.org/en/topics/ai-principles.html', '[{"title":"OECD AI Principles","url":"https://www.oecd.org/en/topics/ai-principles.html"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000006', 'UNESCO Recommendation on the Ethics of Artificial Intelligence',
 'Global normative framework grounding AI governance in human dignity, human rights, fairness and human oversight.',
 'Adopted by UNESCO Member States in November 2021, the Recommendation provides values, ten principles and policy action areas spanning data governance, environment, gender, education, labour, health and international cooperation.',
 'Guideline', 'International', NULL, ARRAY['UNESCO','AI ethics','human rights'], 'UNESCO', 'bg-cyan-700', 'Voluntary',
 'Guide Member States and AI actors toward ethical, rights-respecting and environmentally sustainable AI.',
 'Member States and public, private, research and civil-society AI actors.',
 '["Apply proportionality and do-no-harm safeguards","Protect privacy, data and human rights","Maintain transparency, accountability and human oversight","Assess social, environmental and distributional impacts"]'::jsonb,
 ARRAY['Human dignity','Discrimination','Privacy','Safety','Sustainability'], ARRAY['All industries','Government','Education','Healthcare'], 'UNESCO', '2021-11-23', '2021 Recommendation', 'Adopted recommendation',
 'https://www.unesco.org/en/artificial-intelligence/recommendation-ethics', '[{"title":"UNESCO Recommendation","url":"https://www.unesco.org/en/artificial-intelligence/recommendation-ethics"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000007', 'EU AI Act (Regulation 2024/1689)',
 'Binding European Union regulation establishing risk-based rules for AI systems and general-purpose AI models.',
 'Regulation (EU) 2024/1689 establishes harmonized rules for AI placed on the EU market or whose outputs are used in the EU. It prohibits specified practices, imposes extensive obligations for high-risk systems, transparency duties for certain AI and governance rules for general-purpose AI models.',
 'AI Regulation', 'European Union', NULL, ARRAY['EU AI Act','high-risk AI','GPAI'], 'EU', 'bg-blue-600', 'Mandatory',
 'Promote human-centric, trustworthy AI while protecting health, safety, fundamental rights, democracy and the environment.',
 'Providers, deployers, importers, distributors and product manufacturers in or affecting the European Union, including certain organizations outside the EU.',
 '["Classify systems by prohibited, high, transparency or minimal risk","Operate risk management, data governance, documentation and logging controls","Provide human oversight, accuracy, robustness and cybersecurity","Meet transparency, registration, conformity and post-market monitoring duties where applicable"]'::jsonb,
 ARRAY['Prohibited practices','Fundamental rights','High-risk systems','GPAI','Transparency'], ARRAY['All industries','Employment','Finance','Healthcare','Critical infrastructure','Public sector'], 'European Union and EU AI Office', '2024-08-01', 'Regulation (EU) 2024/1689', 'In force; phased application',
 'https://eur-lex.europa.eu/eli/reg/2024/1689/oj?locale=en', '[{"title":"Official Journal text","url":"https://eur-lex.europa.eu/eli/reg/2024/1689/oj?locale=en"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000008', 'Artificial Intelligence and Data Act (AIDA)',
 'Proposed Canadian federal framework for high-impact AI systems; Bill C-27 did not become law in the 44th Parliament.',
 'AIDA formed Part 3 of Canada''s Bill C-27 and proposed obligations for persons responsible for high-impact AI systems, including risk mitigation, monitoring, record keeping, transparency and incident reporting. The parliamentary session ended before enactment, so AIDA is retained as a proposed-policy reference and must not be treated as current binding law.',
 'AI Regulation', 'Canada', NULL, ARRAY['AIDA','Bill C-27','high-impact AI'], 'CA', 'bg-red-600', 'Mandatory',
 'The proposal sought to regulate international and interprovincial trade in AI systems and reduce harm and biased output.',
 'As proposed, private-sector organizations designing, developing, making available or managing high-impact AI systems in Canadian trade and commerce.',
 '["Assess and mitigate risks of harm and biased output","Monitor mitigation effectiveness","Maintain records and publish system descriptions","Report serious incidents to the responsible minister"]'::jsonb,
 ARRAY['High-impact AI','Bias','Consumer harm','Transparency'], ARRAY['Technology','Employment','Finance','Healthcare','Consumer services'], 'Innovation, Science and Economic Development Canada', NULL, 'Bill C-27 (44-1)', 'Proposed; not enacted',
 'https://www.parl.ca/legisinfo/en/bill/44-1/c-27', '[{"title":"Parliament of Canada LEGISinfo","url":"https://www.parl.ca/legisinfo/en/bill/44-1/c-27"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official","legalNotice":"Proposal was not enacted"}'::jsonb, false),

('10000000-0000-4000-8000-000000000009', 'California AB 2830',
 'Requested citation retained for accuracy: AB 2830 is a California CARE Court and child-welfare measure, not an AI regulation.',
 'California AB 2830 does not establish AI transparency or automated-decision requirements. The 2021-2022 measure concerns the Community Assistance, Recovery, and Empowerment Court Program, while a later 2024 AB 2830 concerns resource-family approval. California''s 2024 election deepfake measure is AB 2839. Norix displays this clarification to prevent a compliance team from relying on a miscitation.',
 'Guideline', 'United States', 'California', ARRAY['citation clarification','CARE Act','not AI-specific'], 'CA', 'bg-amber-600', 'Mandatory',
 'Prevent the requested bill number from being incorrectly treated as an AI compliance obligation.',
 'California behavioral-health and child-welfare programs; no AI-governance scope.',
 '["Confirm the applicable legislative session and bill number","Do not map AB 2830 as an AI control source","Review AB 2839 separately for election deepfake requirements"]'::jsonb,
 ARRAY['Legal citation risk','Regulatory mapping'], ARRAY['Healthcare','Public sector'], 'California Legislature', '2023-07-01', 'AB 2830', 'In force; not AI-specific',
 'https://leginfo.legislature.ca.gov/faces/billTextClient.xhtml?bill_id=202120220AB2830', '[{"title":"Official AB 2830 bill text","url":"https://leginfo.legislature.ca.gov/faces/billTextClient.xhtml?bill_id=202120220AB2830"},{"title":"California AB 2839 deepfake bill","url":"https://leginfo.legislature.ca.gov/faces/billTextClient.xhtml?bill_id=202320240AB2839"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official","citationWarning":true}'::jsonb, false),

('10000000-0000-4000-8000-000000000010', 'Colorado AI Act SB 205',
 'Binding Colorado consumer-protection law governing developers and deployers of high-risk AI systems.',
 'Colorado SB24-205 requires reasonable care to protect consumers from known or reasonably foreseeable algorithmic discrimination. It establishes developer disclosures, deployer risk-management programs and impact assessments, consumer notices and rights, and Attorney General enforcement as a deceptive trade practice.',
 'AI Regulation', 'United States', 'Colorado', ARRAY['Colorado AI Act','high-risk AI','algorithmic discrimination'], 'CO', 'bg-blue-700', 'Mandatory',
 'Protect Colorado consumers from algorithmic discrimination in consequential decisions.',
 'Developers and deployers of high-risk AI used for consequential decisions involving Colorado consumers, subject to statutory exemptions.',
 '["Maintain an AI risk management policy and program","Complete and periodically review impact assessments","Provide required developer, deployer and consumer disclosures","Offer correction, appeal and human-review processes where required"]'::jsonb,
 ARRAY['Algorithmic discrimination','Consequential decisions','Consumer rights','Transparency'], ARRAY['Employment','Finance','Housing','Healthcare','Insurance','Education'], 'Colorado Attorney General', '2026-02-01', 'SB24-205', 'Enacted',
 'https://leg.colorado.gov/bills/sb24-205', '[{"title":"Colorado General Assembly SB24-205","url":"https://leg.colorado.gov/bills/sb24-205"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000011', 'Colorado SB21-169',
 'Colorado insurance law prohibiting unfair discrimination from external consumer data, algorithms and predictive models.',
 'SB21-169 authorizes rules and oversight addressing insurers'' use of external consumer data and information sources, algorithms and predictive models. Insurers must govern these tools so their use does not result in unfair discrimination against protected classes.',
 'AI Regulation', 'United States', 'Colorado', ARRAY['insurance','predictive models','unfair discrimination'], 'CO', 'bg-indigo-700', 'Mandatory',
 'Ensure fair and equitable access to insurance products when insurers use data, algorithms and predictive models.',
 'Insurers authorized to do business in Colorado and their use of external consumer data, algorithms and predictive models in insurance practices.',
 '["Inventory external data, algorithms and predictive models","Establish governance and risk controls","Test and document outcomes for unfair discrimination","Provide information and attestations required by insurance rules"]'::jsonb,
 ARRAY['Proxy discrimination','Protected classes','Model governance','Data quality'], ARRAY['Insurance'], 'Colorado Division of Insurance', '2021-09-06', 'SB21-169', 'In force',
 'https://leg.colorado.gov/sites/default/files/2021a_169_signed.pdf', '[{"title":"Signed SB21-169","url":"https://leg.colorado.gov/sites/default/files/2021a_169_signed.pdf"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000012', 'EEOC Technical Assistance on ADA and AI',
 'Federal technical assistance on avoiding disability discrimination when software, algorithms or AI assess applicants and employees.',
 'The EEOC explains how employer use of algorithmic decision tools can violate Title I of the Americans with Disabilities Act. It highlights accommodation processes, risks that tools screen out qualified people with disabilities, and restrictions on disability-related inquiries and medical examinations.',
 'Guideline', 'United States', NULL, ARRAY['EEOC','ADA','employment AI'], 'EEOC', 'bg-blue-800', 'Voluntary',
 'Help employers and technology vendors prevent disability discrimination when using algorithmic employment tools.',
 'Employers covered by the ADA, employment agencies, HR teams and vendors that design or supply employment assessment tools.',
 '["Provide a clear reasonable-accommodation process","Assess whether tools screen out people with disabilities","Validate that measured traits relate to job performance","Avoid prohibited disability inquiries and medical examinations"]'::jsonb,
 ARRAY['Disability discrimination','Accessibility','Employment decisions','Vendor risk'], ARRAY['Employment','Human resources','Technology'], 'U.S. Equal Employment Opportunity Commission', '2022-05-12', '2022 Technical Assistance', 'Guidance; underlying ADA obligations are binding',
 'https://www.eeoc.gov/eeoc-disability-related-resources/artificial-intelligence-and-ada', '[{"title":"EEOC Artificial Intelligence and the ADA","url":"https://www.eeoc.gov/eeoc-disability-related-resources/artificial-intelligence-and-ada"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000013', 'Illinois HB3773',
 'Illinois Human Rights Act amendment regulating discriminatory AI use and notice in employment decisions.',
 'Illinois HB3773 prohibits employers from using AI in recruitment, hiring, promotion, training, discharge, discipline and other employment terms when it causes discrimination based on protected classes or uses ZIP codes as a proxy. Employers must provide notice of covered AI use.',
 'AI Regulation', 'United States', 'Illinois', ARRAY['employment','notice','discrimination'], 'IL', 'bg-violet-700', 'Mandatory',
 'Prevent protected-class discrimination from AI used in employment and ensure employees receive notice.',
 'Illinois employers using AI for specified employment decisions and employment conditions.',
 '["Identify AI used in covered employment decisions","Provide required employee notices","Test outcomes for protected-class discrimination","Prevent ZIP codes or other features from acting as prohibited proxies"]'::jsonb,
 ARRAY['Employment discrimination','Proxy variables','Notice','Protected classes'], ARRAY['Employment','Human resources'], 'Illinois Department of Human Rights', '2026-01-01', 'Public Act 103-0804 / HB3773', 'In force',
 'https://www.ilga.gov/documents/legislation/103/HB/PDF/10300HB3773lv.pdf', '[{"title":"Enrolled HB3773","url":"https://www.ilga.gov/documents/legislation/103/HB/PDF/10300HB3773lv.pdf"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000014', 'NYC Local Law 144',
 'New York City law requiring annual independent bias audits, public summaries and notices for automated employment decision tools.',
 'Local Law 144 prohibits employers and employment agencies from using a covered automated employment decision tool in New York City unless it received an independent bias audit within the prior year, a summary is publicly available and required notices are provided to candidates and employees.',
 'AI Regulation', 'United States', 'New York City', ARRAY['AEDT','bias audit','employment'], 'NYC', 'bg-slate-700', 'Mandatory',
 'Increase transparency and identify disparate outcomes in automated hiring and promotion tools.',
 'Employers and employment agencies using covered AEDTs to substantially assist hiring or promotion decisions in New York City.',
 '["Obtain an independent bias audit no more than one year before use","Publish the audit summary and distribution data","Give candidates and employees advance notice","Disclose data sources, data types and retention information as required"]'::jsonb,
 ARRAY['Hiring bias','Disparate impact','Transparency','Independent assurance'], ARRAY['Employment','Human resources'], 'NYC Department of Consumer and Worker Protection', '2023-01-01', 'Local Law 144 of 2021', 'In force; enforced since July 5, 2023',
 'https://www.nyc.gov/site/dca/about/automated-employment-decision-tools.page', '[{"title":"NYC DCWP AEDT page","url":"https://www.nyc.gov/site/dca/about/automated-employment-decision-tools.page"},{"title":"NYC Local Law 144 legislation","url":"https://legistar.council.nyc.gov/LegislationDetail.aspx?GUID=B051915D-A9AC-451E-81F8-6596032FA3F9&ID=4344524"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000015', 'UK AI White Paper',
 'United Kingdom pro-innovation, principles-based approach implemented through existing sector regulators.',
 'The 2023 White Paper proposes a context-sensitive framework rather than a single AI-specific regulator. Existing regulators interpret five cross-sector principles within their remits: safety and robustness, transparency and explainability, fairness, accountability and governance, and contestability and redress.',
 'Framework', 'United Kingdom', NULL, ARRAY['UK','pro-innovation','regulatory principles'], 'UK', 'bg-blue-900', 'Voluntary',
 'Support responsible AI innovation through adaptable, sector-led application of common regulatory principles.',
 'Organizations developing or using AI in areas supervised by existing UK regulators.',
 '["Assess safety, security and robustness","Provide appropriate transparency and explainability","Address fairness and legal rights","Establish accountability, governance, contestability and redress"]'::jsonb,
 ARRAY['Safety','Transparency','Fairness','Accountability','Redress'], ARRAY['All regulated industries'], 'UK Department for Science, Innovation and Technology', '2023-03-29', 'Command Paper 815', 'Policy framework',
 'https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach', '[{"title":"UK AI regulation White Paper","url":"https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000016', 'Australian AI Ethics Principles',
 'Eight voluntary principles for safe, secure, reliable, fair, transparent and accountable AI.',
 'Australia''s AI Ethics Principles guide organizations designing, developing and implementing AI. The principles cover human and societal well-being, human-centred values, fairness, privacy and security, reliability and safety, transparency and explainability, contestability and accountability.',
 'Guideline', 'Australia', NULL, ARRAY['Australia','AI ethics','responsible AI'], 'AU', 'bg-emerald-700', 'Voluntary',
 'Build public trust and help organizations achieve safer, fairer and more reliable AI outcomes.',
 'Businesses and governments designing, developing, deploying or operating AI in Australia.',
 '["Assess human, social and environmental benefit","Protect human-centred values, fairness and privacy","Maintain reliability, safety and security","Provide transparency, contestability and accountable ownership"]'::jsonb,
 ARRAY['Human wellbeing','Fairness','Privacy','Reliability','Contestability'], ARRAY['All industries','Public sector'], 'Australian Department of Industry, Science and Resources', '2019-11-07', '2019 Principles', 'Voluntary principles',
 'https://www.industry.gov.au/science-technology-and-innovation/technology/artificial-intelligence', '[{"title":"Australian Government AI policy","url":"https://www.industry.gov.au/science-technology-and-innovation/technology/artificial-intelligence"},{"title":"AI Ethics Framework consultation and final principles","url":"https://consult.industry.gov.au/australias-ai-ethics-framework"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000017', 'AI Verify Framework',
 'Singapore AI governance testing framework and toolkit using process checks and standardized technical tests.',
 'AI Verify was developed by Singapore''s IMDA and PDPC to help organizations validate claimed AI performance against internationally recognized governance principles. It covers transparency, explainability, reproducibility, safety, security, robustness, fairness, data governance, accountability, human agency and societal well-being.',
 'Framework', 'Singapore', NULL, ARRAY['AI Verify','assurance','testing'], 'SG', 'bg-red-700', 'Voluntary',
 'Enable objective and repeatable testing that improves transparency between AI owners and stakeholders.',
 'AI developers, owners and deployers seeking technical testing and process assurance for traditional or generative AI.',
 '["Document governance process checks","Run applicable fairness, explainability and robustness tests","Evaluate safety, security and data governance","Generate and review an AI Verify testing report"]'::jsonb,
 ARRAY['Fairness','Explainability','Robustness','Safety','Data governance'], ARRAY['All industries'], 'Singapore Infocomm Media Development Authority and AI Verify Foundation', '2022-05-25', 'AI Verify open-source framework', 'Voluntary framework',
 'https://www.imda.gov.sg/how-we-can-help/ai-verify', '[{"title":"IMDA AI Verify","url":"https://www.imda.gov.sg/how-we-can-help/ai-verify"},{"title":"AI Verify launch","url":"https://www.imda.gov.sg/resources/press-releases-and-factsheets/press-releases/2022/singapore-launches-worlds-first-ai-testing-framework-and-toolkit-to-promote-transparency-invites-companies-to-pilot-and-contribute-to-international-standards-development"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false),

('10000000-0000-4000-8000-000000000018', 'California AB 2839 — Election Deepfakes',
 'California law addressing materially deceptive AI-generated or manipulated election communications.',
 'AB 2839 expands restrictions and remedies concerning materially deceptive election content, including deepfake audio and visual media that falsely portrays candidates, elected officials, election officials or election-related equipment. It includes disclosure rules and specified exceptions.',
 'AI Regulation', 'United States', 'California', ARRAY['deepfakes','elections','synthetic media'], 'CA', 'bg-amber-600', 'Mandatory',
 'Protect election integrity and voters from materially deceptive synthetic media.',
 'Persons and entities distributing covered election communications in California during statutory periods, subject to exceptions and constitutional limitations.',
 '["Identify covered materially deceptive election content","Apply required manipulation disclosures where an exception permits distribution","Maintain provenance and review processes for political content","Support prompt removal or legal response where statutory remedies apply"]'::jsonb,
 ARRAY['Deepfakes','Election integrity','Misinformation','Content provenance'], ARRAY['Media','Advertising','Political campaigns','Technology platforms'], 'California Secretary of State and California courts', '2024-09-17', 'AB 2839 (2024)', 'Enacted; provisions subject to litigation and statutory timing',
 'https://leginfo.legislature.ca.gov/faces/billTextClient.xhtml?bill_id=202320240AB2839', '[{"title":"Official AB 2839 bill text","url":"https://leginfo.legislature.ca.gov/faces/billTextClient.xhtml?bill_id=202320240AB2839"}]'::jsonb, false,
 '{"libraryVersion":"2026.1","sourceType":"official"}'::jsonb, false)
